using System.Collections.Generic;
using UnityEngine;
public sealed class GridShiftRouteView:MonoBehaviour {
 public bool showInWorld;public Color routeColor=new Color(.3f,.85f,1);[Range(0,1)]public float transparency=.72f;
 [Range(1,8)]public float mapWidth=2.6f;[Range(.025f,.25f)]public float worldWidth=.08f;[Min(5)]public float viewDistance=70;
 public Color RouteColor=>new Color(routeColor.r,routeColor.g,routeColor.b,transparency);
 readonly List<Vector3> points=new List<Vector3>();readonly List<LineRenderer> ribbons=new List<LineRenderer>();DeliveryManager manager;Material material;float next;
 void Awake(){manager=GetComponent<DeliveryManager>();showInWorld=PlayerPrefs.GetInt("GS.Route.World",0)!=0;mapWidth=PlayerPrefs.GetFloat("GS.Route.MapWidth",2.6f);worldWidth=PlayerPrefs.GetFloat("GS.Route.WorldWidth",.08f);transparency=PlayerPrefs.GetFloat("GS.Route.Alpha",.72f);viewDistance=PlayerPrefs.GetFloat("GS.Route.Distance",70);routeColor=PlayerPrefs.GetInt("GS.Route.Blue",0)==1?new Color(.2f,.6f,1):new Color(.3f,.85f,1);}
 void Update(){if(Time.unscaledTime<next)return;next=Time.unscaledTime+.2f;foreach(var line in ribbons)line.gameObject.SetActive(false);if(!showInWorld||Camera.main==null||!GridShiftTrackedRoute.BuildForMap(manager,points))return;int used=0;for(int i=1;i<points.Count;i++){int steps=Mathf.CeilToInt(Vector3.Distance(points[i-1],points[i]));Vector3? prior=null;for(int k=0;k<=steps;k++){var at=Vector3.Lerp(points[i-1],points[i],k/(float)Mathf.Max(1,steps));if(Vector3.Distance(Camera.main.transform.position,at)>viewDistance||!Road(at,out var road)){prior=null;continue;}if(prior.HasValue){if(used==ribbons.Count){var go=new GameObject("TrackedRoadRibbon");go.layer=11;go.transform.SetParent(transform);var line=go.AddComponent<LineRenderer>();line.positionCount=2;line.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;line.receiveShadows=false;if(material==null){var source=GetComponent<DeliveryPresentation>().destinationMaterial;if(source==null)return;material=new Material(source);material.color=Color.white;}line.sharedMaterial=material;ribbons.Add(line);}var ribbon=ribbons[used++];ribbon.gameObject.SetActive(true);ribbon.widthMultiplier=worldWidth;ribbon.startColor=ribbon.endColor=RouteColor;ribbon.SetPosition(0,prior.Value);ribbon.SetPosition(1,road);}prior=road;}}}
 static bool Road(Vector3 at,out Vector3 point){point=at;if(!Physics.Raycast(at+Vector3.up*2,Vector3.down,out var hit,4,~((1<<9)|(1<<10)|(1<<11)),QueryTriggerInteraction.Ignore)||hit.normal.y<.85f)return false;string name=hit.collider.name.ToLowerInvariant();if(!name.Contains("road")&&!name.Contains("street")&&!name.Contains("asphalt")&&!name.Contains("rua"))return false;point=hit.point+Vector3.up*.035f;return true;}
 public void SavePreferences(){PlayerPrefs.SetInt("GS.Route.World",showInWorld?1:0);PlayerPrefs.SetFloat("GS.Route.MapWidth",mapWidth);PlayerPrefs.SetFloat("GS.Route.WorldWidth",worldWidth);PlayerPrefs.SetFloat("GS.Route.Alpha",transparency);PlayerPrefs.SetFloat("GS.Route.Distance",viewDistance);PlayerPrefs.SetInt("GS.Route.Blue",routeColor.g<.7f?1:0);}
 void OnDestroy(){if(material!=null)Destroy(material);}
}
